using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

namespace MoonwellEditor.BridgeTypes;

/// <summary>
/// Writes the page's TypeScript for what crosses the bridge. Each type is read from the serializer's own contract (the
/// names it writes, which properties can be null, the text of each enum value), so the page's types say what the bridge
/// really sends.
/// </summary>
public static class TypeScriptWriter
{
    /// <summary>The first line of the file.</summary>
    public const string Header =
        "// Generated by tools/MoonwellEditor.BridgeTypes from the C# types. Do not edit: run `npm run types` in web.";

    /// <summary>Writes the file.</summary>
    /// <param name="shape">What crosses the bridge.</param>
    /// <param name="answers">The options the bridge writes answers and events with.</param>
    /// <param name="arguments">The options the bridge reads arguments with.</param>
    /// <param name="docs">The docs to copy.</param>
    /// <returns>The file's text.</returns>
    /// <exception cref="BridgeTypesException">A type cannot be written, or two have the same name.</exception>
    public static string Write(
        BridgeShape shape, JsonSerializerOptions answers, JsonSerializerOptions arguments, DocComments docs) =>
        new Writer(shape, answers, arguments, docs).Write();

    private enum Side
    {
        Answer,
        Argument,
    }

    private sealed class Writer(
        BridgeShape shape, JsonSerializerOptions answers, JsonSerializerOptions arguments, DocComments docs)
    {
        private readonly Dictionary<string, Type> _names = new(StringComparer.Ordinal);

        // Each type's declaration as an answer and as arguments; null while it is being written (a type that holds
        // itself).
        private readonly Dictionary<(Type Type, Side Side), string?> _declarations = [];

        public string Write()
        {
            var commands = new List<string>();
            var tells = new List<string>();
            foreach (var command in shape.Commands.OrderBy(command => command.Name, StringComparer.Ordinal))
            {
                var args = Reference(command.Args, Side.Argument, command.Name);
                if (command.Told)
                {
                    tells.Add($"  {command.Name}: {args};");
                    continue;
                }

                var answer = command.Answer == null ? "null" : Reference(command.Answer, Side.Answer, command.Name);
                if (command.AnswerNullable && command.Answer != null)
                {
                    answer += " | null";
                }

                commands.Add($"  {command.Name}: {{ args: {args}; answer: {answer} }};");
            }

            var events = shape.Events
                .OrderBy(@event => @event.Name, StringComparer.Ordinal)
                .Select(@event => $"  {@event.Name}: {Reference(@event.Payload, Side.Answer, @event.Name)};")
                .ToList();
            foreach (var other in shape.Others)
            {
                Reference(other, Side.Answer, other.Name);
            }

            var parts = new List<string> { Header + "\n" };
            parts.AddRange(Declarations());
            parts.Add(Block("Commands", commands));
            parts.Add(Block("Tells", tells));
            parts.Add(Block("Events", events));
            parts.Add($"export type ErrorCode = {Union(shape.ErrorCode, answers)};\n");
            return string.Join("\n", parts);
        }

        private IEnumerable<string> Declarations()
        {
            foreach (var (name, type) in _names.OrderBy(pair => pair.Key, StringComparer.Ordinal))
            {
                if (type == shape.ErrorCode)
                {
                    continue;
                }

                _declarations.TryGetValue((type, Side.Answer), out var asAnswer);
                _declarations.TryGetValue((type, Side.Argument), out var asArgument);
                if (asAnswer != null && asArgument != null && asAnswer != asArgument)
                {
                    throw new BridgeTypesException(
                        $"{type.FullName} is both an answer and arguments, and reads differently as each: give the "
                        + "arguments a record of their own.");
                }

                var doc = docs.OfType(type) is { } text ? $"/** {text} */\n" : "";
                yield return doc + (asAnswer ?? asArgument);
            }
        }

        private static string Block(string name, List<string> entries) =>
            $"export type {name} = {{\n{string.Concat(entries.Select(entry => entry + "\n"))}}};\n";

        // The TypeScript for a type where it is used, declaring it first when it is a record or an enum.
        private string Reference(Type type, Side side, string path)
        {
            if (Nullable.GetUnderlyingType(type) is { } inner)
            {
                return Reference(inner, side, path);
            }

            if (type == typeof(string) || type == typeof(char))
            {
                return "string";
            }

            if (type == typeof(bool))
            {
                return "boolean";
            }

            if (type == typeof(JsonElement))
            {
                return "unknown";
            }

            if (IsNumber(type))
            {
                return "number";
            }

            var info = Options(side).GetTypeInfo(type);
            switch (info.Kind)
            {
                case JsonTypeInfoKind.Enumerable:
                    return $"{Reference(info.ElementType!, side, path)}[]";
                case JsonTypeInfoKind.Dictionary:
                    var key = info.KeyType!;
                    var value = Reference(info.ElementType!, side, path);
                    if (key == typeof(string))
                    {
                        return $"Record<string, {value}>";
                    }

                    if (key.IsEnum)
                    {
                        return $"Partial<Record<{Reference(key, side, path)}, {value}>>";
                    }

                    throw Unmappable(type, path);
                case JsonTypeInfoKind.Object when !type.IsInterface && !type.IsGenericType && type != typeof(object):
                case JsonTypeInfoKind.None when type.IsEnum:
                    return Declare(type, side, path);
                default:
                    throw Unmappable(type, path);
            }
        }

        private string Declare(Type type, Side side, string path)
        {
            if (_names.TryGetValue(type.Name, out var known) && known != type)
            {
                throw new BridgeTypesException(
                    $"{known.FullName} and {type.FullName} would both be {type.Name} on the page (reached at {path}).");
            }

            _names[type.Name] = type;
            if (_declarations.ContainsKey((type, side)))
            {
                return type.Name;
            }

            _declarations[(type, side)] = null;
            _declarations[(type, side)] = type.IsEnum
                ? $"export type {type.Name} = {Union(type, Options(side))};\n"
                : Record(type, side);
            return type.Name;
        }

        private string Record(Type type, Side side)
        {
            var info = Options(side).GetTypeInfo(type);
            var properties = info.Properties
                .Where(property => side == Side.Answer
                    ? property.Get != null
                    : property.Set != null || property.AssociatedParameter != null)
                .ToList();
            if (properties.Count == 0)
            {
                return $"export type {type.Name} = Record<string, never>;\n";
            }

            var text = new StringBuilder($"export type {type.Name} = {{\n");
            foreach (var property in properties)
            {
                var path = $"{type.Name}.{property.Name}";
                var clrName = (property.AttributeProvider as MemberInfo)?.Name ?? property.Name;
                if (docs.OfProperty(type, clrName) is { } doc)
                {
                    text.Append($"  /** {doc} */\n");
                }

                var optional = side == Side.Argument && property.AssociatedParameter?.HasDefaultValue == true;
                var nullable = side == Side.Answer
                    ? property.IsGetNullable
                    : property.AssociatedParameter?.IsNullable ?? property.IsSetNullable;
                var reference = Reference(property.PropertyType, side, path);
                text.Append($"  {property.Name}{(optional ? "?" : "")}: {reference}{(nullable ? " | null" : "")};\n");
            }

            return text.Append("};\n").ToString();
        }

        // Each value as the serializer writes it: "unit", "StartLocation", or 0 for an enum written as numbers.
        private static string Union(Type type, JsonSerializerOptions options) => string.Join(
            " | ",
            Enum.GetValues(type).Cast<object>().Select(value => JsonSerializer.Serialize(value, type, options)));

        private JsonSerializerOptions Options(Side side) => side == Side.Answer ? answers : arguments;

        private static bool IsNumber(Type type) =>
            Type.GetTypeCode(type) is TypeCode.Byte or TypeCode.SByte or TypeCode.Int16 or TypeCode.UInt16
                or TypeCode.Int32 or TypeCode.UInt32 or TypeCode.Int64 or TypeCode.UInt64 or TypeCode.Single
                or TypeCode.Double or TypeCode.Decimal
            && !type.IsEnum;

        private static BridgeTypesException Unmappable(Type type, string path) =>
            new($"{path} is a {type.FullName}, which the page has no type for.");
    }
}
